<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('recruiter');$user=current_user();$flashes=render_flashes();$currentPage='talent_pool';$pageTitle='Talent Pool';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$rows=[];if(rc_has_table($conn,'skills')&&rc_has_table($conn,'candidate_skills')){$r=$conn->query("SELECT s.name,s.category,s.is_scarce,COUNT(DISTINCT CASE WHEN cs.verification_status='verified' THEN cs.candidate_id END) verified_candidates,MAX(cs.verified_at) latest FROM skills s LEFT JOIN candidate_skills cs ON cs.skill_id=s.id GROUP BY s.id,s.name,s.category,s.is_scarce ORDER BY s.is_scarce DESC,verified_candidates DESC,s.name");while($r&&$x=$r->fetch_assoc())$rows[]=$x;}require __DIR__.'/_layout_start.php';?><div class="rc-page-header"><span class="rc-eyebrow">Talent Intelligence</span><h2>Talent Pool</h2><p>Verified candidate supply across the active skill taxonomy.</p></div><div class="rc-card"><div class="rc-table-wrap"><table class="rc-table"><thead><tr><th>Skill</th><th>Category</th><th>Scarcity</th><th>Verified Candidates</th><th>Latest Verification</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><strong><?=e($x['name'])?></strong></td><td><?=e((string)($x['category']?:'General'))?></td><td><?= $x['is_scarce']?'<span class="rc-status rc-status--purple">Scarce</span>':'Standard' ?></td><td><?=number_format((int)$x['verified_candidates'])?></td><td><?=e(rc_date($x['latest']))?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/_layout_end.php';?>